interface.definition:
a!localVariables(
  local!carColor: a!match(
    value: lower(
      trim(
        ri!vehicle[#"urn:appian:record-field:v1:4319b3e4-ca07-43be-8557-19466417914e/a21ed1e0-2a0e-4992-acfd-db67a1158890"]
      )
    ),
    equals: "black",
    then: "#000000",
    equals: "blue",
    then: "#0747AD",
    equals: "brown",
    then: "#8B4513",
    equals: "yellow",
    then: "#D4AF37",
    equals: "grey",
    then: "#808080",
    equals: "green",
    then: "#185922",
    equals: "red",
    then: "#D32F2F",
    equals: "silver",
    then: "#C0C0C0",
    equals: "white",
    then: "#F9F9F9",
    default: "#BCBCBC"
  ),
