                      "Details"
                    },
                    size: "MEDIUM_PLUS",
                    style: {
                      "STRONG"
                    }
                  )
                }
              ),
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                label: "",
                labelSize: "MEDIUM_PLUS",
                labelColor: "STANDARD",
