                            value: if(
                              isnull(
                                fv!row[#"urn:appian:record-field:v1:56e24fa4-b6b0-49e6-a8c4-99845ebcfe9d/24db7e49-d0d7-4dff-a8f3-06445dfb193c"]
                              ),
                              "–",
                              datetext(
                                fv!row[#"urn:appian:record-field:v1:56e24fa4-b6b0-49e6-a8c4-99845ebcfe9d/24db7e49-d0d7-4dff-a8f3-06445dfb193c"],
                                "default"
                              )
