                                  identifier: fv!row[#"urn:appian:record-field:v1:56e24fa4-b6b0-49e6-a8c4-99845ebcfe9d/d8e08124-17bb-4612-81b3-57503af99a15"]
                                ),
                                #"SYSTEM_SYSRULES_recordActionItem"(
                                  action: #"urn:appian:record-action:v1:56e24fa4-b6b0-49e6-a8c4-99845ebcfe9d/d864edf3-5914-4695-b34e-fa636525129f",
                                  identifier: fv!row[#"urn:appian:record-field:v1:56e24fa4-b6b0-49e6-a8c4-99845ebcfe9d/d8e08124-17bb-4612-81b3-57503af99a15"]
                                )
